// --- Hillshade-Berechnungsfunktion (wie im OL-Beispiel)
function shade(inputs, data) {
  const elevationImage = inputs[0];
  const width = elevationImage.width;
  const height = elevationImage.height;
  const elevationData = elevationImage.data;
  const shadeData = new Uint8ClampedArray(elevationData.length);

  const dp = data.resolution * 2;
  const maxX = width - 1;
  const maxY = height - 1;
  const pixel = [0, 0, 0, 0];
  const sunEl = (Math.PI * data.sunEl) / 180;
  const sunAz = (Math.PI * data.sunAz) / 180;
  const cosSunEl = Math.cos(sunEl);
  const sinSunEl = Math.sin(sunEl);

  function getZ(offset) {
    pixel[0] = elevationData[offset];
    pixel[1] = elevationData[offset + 1];
    pixel[2] = elevationData[offset + 2];
    // einfache Skalierung – ggf. anpassen je nach Kodierung
    return pixel[0] * 256 + pixel[1] + pixel[2] / 256 - 32768;
  }

  for (let y = 0; y <= maxY; ++y) {
    const y0 = y === 0 ? 0 : y - 1;
    const y1 = y === maxY ? maxY : y + 1;
    for (let x = 0; x <= maxX; ++x) {
      const x0 = x === 0 ? 0 : x - 1;
      const x1 = x === maxX ? maxX : x + 1;

      const dzdx = (getZ((y * width + x1) * 4) - getZ((y * width + x0) * 4)) / dp;
      const dzdy = (getZ((y1 * width + x) * 4) - getZ((y0 * width + x) * 4)) / dp;

      const slope = Math.atan(Math.sqrt(dzdx * dzdx + dzdy * dzdy));
      const aspect = Math.atan2(dzdy, -dzdx);
      const cosInc =
        sinSunEl * Math.cos(slope) +
        cosSunEl * Math.sin(slope) * Math.cos(sunAz - aspect);

      const shade = 255 * Math.max(0, cosInc);
      const off = (y * width + x) * 4;
      shadeData[off] = shade;
      shadeData[off + 1] = shade;
      shadeData[off + 2] = shade;
      shadeData[off + 3] = 255;
    }
  }

  return { data: shadeData, width, height, colorSpace: 'srgb' };
}

// --- Raster-Quelle mit Hillshade
const raster = new RasterSource({
  sources: [elevation],
  operationType: 'image',
  operation: shade,
});

